import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/02-People-started-programming-over-800-years-ago.html","title":"03-八百多年前的人就开始编程了？","lang":"zh-CN","frontmatter":{"title":"03-八百多年前的人就开始编程了？","icon":"read","date":"2025-04-11T13:49:23.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1744355058000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":13,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"fce1e04345eee5de33e4a1bb5843705462619b17","time":1744355058000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"image"},{"hash":"1f429403468a1434cab5badb5e5027ff02e5181a","time":1744352710000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"d1a803e1b0d022b5d20a696fa0692d339b8ff140","time":1744351721000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"创建 init"},{"hash":"2b312ff09a729c21916e9f55a427e204e65b3e4d","time":1744350615000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"true"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":9.24,"words":2773},"filePathRelative":"column/Programmingthinking/02-People-started-programming-over-800-years-ago.md"}`),a={name:`02-People-started-programming-over-800-years-ago.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>我问你一个问题：<strong>编程到底是什么？</strong>听到这个问题，你可能会觉得好笑：这个问题怎么这么简单啊，我还会不知道编程是什么嘛！编程不就是用电脑写出一行行代码，然后做出一个<strong>小程序或者小游戏</strong>嘛。而且，也许你已经学过编程，甚至尝试着自己用代码创造了自己的小游戏。</p><p>其实啊，在这门课程里，我就是要让你体会到，编程原来并不只是写一行行代码这么简单<strong>。编程是要告诉机器，在什么时候做什么样的事情。</strong>诶，你可能注意到了，在刚才那句话里，我说的是“机器”而不是“电脑”。那是因为，编程并不一定要靠电脑。实际上，在电脑出现之前很久，人们就已经开始编程了。可是，没有电脑怎么编程呢？诶，这就要说到编程的起源了。</p><p>现在咱们说编程的起源这件事儿啊，一般来说，都会<strong>追溯</strong>到800多年前。当时，在阿拉伯帝国，有一个<strong>聪明又能干</strong>的发明家，叫做<strong>伊斯梅尔·加扎利</strong>。他发明了很多有意思的小物件，其中最有名的一件，是一条<strong>小船</strong>。</p><p>没错，就是一条可以漂浮在水面上的小船。你可能会疑惑了，小船有什么了不起的啊，我也会折小纸船啊。不过，加扎利的这条小船可就厉害了。</p><p>船上坐着一位国王和几位贵族，他们在开宴会，喝酒呢。在船的角落里，还坐着<strong>4位音乐家</strong>，两位负责打鼓，一位负责弹竖琴，还有一位吹笛子。他们在演奏动听的音乐。虽然技术高超，但这些音乐家都不会说话，也不能喝酒。因为，他们都是<strong>木头人</strong>。</p><figure><img src="/assets/25c43da766b180d0a0310c3563c744cd-4352107-qPXRu6Ic.jpg" alt="伊斯梅尔设计的音乐机器人" tabindex="0" loading="lazy"><figcaption>伊斯梅尔设计的音乐机器人</figcaption></figure><p>诶，问题来了，木头人是怎么演奏音乐的呢？这里头的秘密跟<strong>八音盒</strong>有关。八音盒你一定玩过吧，只要给八音盒上好发条，它就会开始旋转，并且发出清脆的音乐声。</p><p>如果你拆开过八音盒，就会发现它的核心零件是一个<strong>圆柱形金属</strong>。在这个圆柱形上边，有很多小小的<strong>凸起</strong>。圆柱形金属旋转起来之后，金属片上的那小凸起就起到了手指的作用，按照一定的规律拨动八音盒里的<strong>琴键</strong>。音乐就这样响起来了。</p><p>听到这里，你想到加扎利是怎么做的了吗？</p><p>没错，加扎利也在船里安装了一个八音盒。在这部机器里头，也有一个金属圆柱。而且，他这个圆柱形上边的小凸起是活动的，可以取下来重新安装，<strong>改变位置</strong>，这样一来，木头音乐家就能演奏出不同的音乐了。</p><p>我在屏幕上放了一张<strong>加扎利音乐船</strong>的图片。图片的最左侧就是四位音乐家，他们的座位下面，就能看到那个金属圆柱。</p><figure><img src="/assets/b37739dbe1cb96c364391d8768276046-cys05imS.jpg" alt="加扎利音乐船" tabindex="0" loading="lazy"><figcaption>加扎利音乐船</figcaption></figure><p>诶，就这样，事先设置好拨动琴键的顺序，让机器在特定时间发出特定的声音，其实就是可以算作最早的编程了。可惜的是，加扎利并没有把这种想法运用到别的领域去。很快，这种制作技巧就失传了。</p><p>后来，一代又一代的发明家，又各自独立地想出了很多编程的主意。其中，对咱们今天影响最大的，是一个叫<strong>霍尔瑞斯</strong>的人。</p><figure><img src="/assets/4f2c5d22503f6068006b6465153757fc-D65P7KTL.jpg" alt="霍尔瑞斯" tabindex="0" loading="lazy"><figcaption>霍尔瑞斯</figcaption></figure><p>霍尔瑞斯是个美国人。那个时候的美国啊，碰到了一个大麻烦。</p><p>这个大麻烦来自美国从建国以后形成的一个传统：每隔10年要进行一次<strong>全国人口大普查</strong>。这是一项非常重要的工作，可不光是数数有几个人那么简单。还要弄清楚某个人，认不认识字呀，是不是有什么疾病，是不是干过什么坏事等等等等，一共有20多个问题呢。</p><p>不过，那个时候，统计这些数据只能靠人工。随着美国的人口越来越多，统计人口普查信息的难度也越来越大了。到1890年，又进行了一次大普查，结果竟然收回来<strong>1000多万份问卷</strong>。普查办公室主任既高兴，又忧愁。高兴当然是因为他收集到了国家的重要数据。忧愁呢，抱着这一大堆数据，不好处理。</p><p>刚才我说了，当时所有的统计工作都是靠手工来做的。如果你每天统计100张问卷，那1000万张，要花270多年才能做完！要是找上30个同学帮你做，那也得花上9年才能做完。</p><p>你还别说，10年前，也就是1880年的普查数据，还真的是花了9年才算出来的。<strong>每10年做一次的人口普查，要花9年才能统计出结果</strong>，这就意味着这些数据刚一出炉就过时了。因为再过一年，就又要开始新的大普查了嘛！这就好比是，你到了4年级期末考试的时候，才交出3年级的暑假作业。碰到这种情况，老师大概也只能朝你翻个白眼了吧。</p><p>更糟的是，1890年的普查，数据更多，要花的时间更长。人们议论纷纷，说普查办公室工作能力不行，没有金刚钻硬揽瓷器活，真是不知道天高地厚。</p><p>可是，人口普查那可是法律规定的，而且的确特别重要，无论如何都得做。但硬做的话，又实在是太慢了，这可怎么办呢？普查办公室主任想出来一个好主意，在1890年人口大普查开始之前，他就宣布：如果有谁能够又快又好地统计数据，我就把这个活安排给谁干。钱管够、饭管饱！</p><p>危难之际总有英雄出现，这次，一个年轻的小伙子站出来了，他就是霍尔瑞斯。霍尔瑞斯发明了一种新机器，叫“<strong>打孔卡片制表机</strong>”。这台机器呢，有点像一台打印机，把一摞摞打了孔的卡片塞进去，统计结果自己就出来了。</p><figure><img src="/assets/9e540b3c42edb209a43a00b9f6b4ef91-DfVBV7pT.jpg" alt="打孔卡片制表机   图片来源：Adam Schuster" tabindex="0" loading="lazy"><figcaption>打孔卡片制表机 图片来源：Adam Schuster</figcaption></figure><p>那这台机器到底靠不靠谱呢？普查办公室特地举办了一场比赛，让霍尔瑞斯和其他拍胸脯保证能解决问题的人，一起当场比试。结果，霍尔瑞斯果然大获全胜。他只花了半天就交卷出场了，而他的对手，最快的，也要忙活2天，才能才交出答卷！毫无疑问，霍尔瑞斯赢了，拿下了这单大生意。</p><p>那么，霍尔瑞斯的机器到底是怎么做的呢？说来也简单，靠的只是<strong>在卡片上打孔</strong>。比如说吧，假设你是一位11岁的男性公民。那么，就可以在你卡片上的“性别”栏底下表示“男性”的位置打一个孔，再在“年龄”栏的“11岁”下边也打一个孔。那么，这两个孔就是表示：你11岁，是个男的。</p><p>如果你的爸爸妈妈也在听这一讲，他们一定会觉得这个做法非常熟悉。他们参加过的一些考试，在答题的时候，就要做类似的事情：用铅笔，在特制的答题卡上，把要选择的答案涂黑。没错，这样的答题方法，跟霍尔瑞斯的机器几乎是一样的。</p><p>卡片打好孔之后，一张卡片就代表了一个人。等所有人的卡片都打完孔了，再把它们全都塞进机器里。机器就会读出小孔代表的信息，再把它们加起来。这样，全美国有多少个男性，有多少人11岁，就全部计算出来了。</p><figure><img src="https://coolcdn.igetcool.com/p/2021/1/706e7e393a34774c836086d112506555.jpg" alt="打孔卡" tabindex="0" loading="lazy"><figcaption>打孔卡</figcaption></figure><p>靠着这台机器，工作人员只用了2年半的时间，就完成了1890年人口大普查的数据统计。从此呢，美国的人口普查也告别了手工计算的旧时代，迎来了机器计算的新时代。霍尔瑞斯也因此赚到了大钱。后来，他开了一家公司专门做这个生意。这家公司就是现在鼎鼎大名的<strong>IBM公司的前身</strong>。IBM公司特别重要，咱们后面的课程里还会提到它。</p><p>听到这儿你可能还会有疑问，打孔跟编程有什么关系啊？</p><p>其实，打孔就是一种编程了！</p><p>还记得我前面说的嘛，编程就是告诉机器该做什么事情。霍尔瑞斯在卡片上打孔，就是创造了一种让机器能听懂的语言，让它知道该记录什么数据，并且能够完成统计任务——这当然就是在编程。</p><p>不过，咱们现在编程只要敲敲键盘、点点鼠标就能完成。霍尔瑞斯的编程方法就费力多了。在一开始的时候，霍尔瑞斯把自己全家的钱都拿来搞发明了，根本没钱雇人在纸上打孔，只好自己亲自上阵。他一天就要给几百张卡片打孔，从白天忙到半夜，打孔打得胳膊都肿了，抬都抬不起来。所以，那个时代的编程完全就是重体力活啊！</p><p>后来呢，霍尔瑞斯发明了打孔机，用机器帮人打孔，就省力多了。而且，最初霍尔瑞斯的机器，只能统计人口数据。那人口数据一统计完，岂不是就没事做了？这可不行，于是霍尔瑞斯又搞出来一项新发明：在机器上加装一个设备，让它也能统计别的数据，什么卫生数据啊、商业数据啊，样样都行！你看，这么一台机器能干很多不同的事情，是不是已经很像今天的电脑程序了呀？</p><p>其实，霍尔瑞斯这种制造一台机器完成多种任务的想法，特别重要，咱们今天能用上方便的计算机都和这种想法有关。下一集，我就来给你说说这种厉害的思维，我们下一集见。</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};